"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[3478],{5199(n,e,a){a.r(e),a.d(e,{assets:()=>p,contentTitle:()=>l,default:()=>u,frontMatter:()=>d,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"part5-deep-learning-and-llms/cnn-dropout-train-eval","title":"CNN Training in PyTorch: Flattening, Dropout, Train, and Eval","description":"This chapter develops Dropout from first principles: what gets masked, how often masks change, why scaling exists, how gradients behave, and why train()/eval() matters.","source":"@site/docs/part5-deep-learning-and-llms/07-cnn-dropout-train-eval.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/07-cnn-dropout-train-eval","permalink":"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":7,"frontMatter":{"title":"CNN Training in PyTorch: Flattening, Dropout, Train, and Eval","slug":"/part5-deep-learning-and-llms/07-cnn-dropout-train-eval","description":"This chapter develops Dropout from first principles: what gets masked, how often masks change, why scaling exists, how gradients behave, and why train()/eval() matters.","sidebar_label":"7. CNN dropout and train/eval","pagination_label":"7. CNN dropout and train/eval","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"6. CNN PyTorch implementation","permalink":"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation"},"next":{"title":"8. Forecasting and sequence data","permalink":"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data"}}');var o=a(4848),i=a(8453),s=a(8172);const r=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/07-cnn-dropout-train-eval.html","route":"/part5-deep-learning-and-llms/07-cnn-dropout-train-eval","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"CNN Training in PyTorch: Conv2d, Custom Models, Flattening, and Dropout","title":"CNN Training in PyTorch: Flattening, Dropout, Train, and Eval","description":"This chapter develops Dropout from first principles: what gets masked, how often masks change, why scaling exists, how gradients behave, and why train()/eval() matters.","readingMinutes":4,"bodyClass":"","normalizeMath":false,"toc":[{"id":"dropout-what-it-actually-does-and-what-it-does-not-do","label":"Dropout: what it actually does (and what it does NOT do)"},{"id":"train-vs-eval-why-dropout-turns-off-for-predictions","label":"train() vs eval(): why dropout \u201cturns off\u201d for predictions"},{"id":"dropout-faq-common-confusions","label":"Dropout FAQ (common confusions)"},{"id":"local-visuals-and-source-credits","label":"Local visuals and source credits"}],"html":"<div class=\\"wrap\\">\\n\\n  <header>\\n    \\n    <p>\\n      This chapter develops Dropout from first principles: what gets masked, how often masks change, why scaling exists,\\n      how gradients behave, and why <code>train()</code>/<code>eval()</code> matters.\\n    </p>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Deep-dive chapter</strong>\\n      <a href=\\"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation\\">Chapter 6</a> introduces\\n      dropout as part of the CNN implementation checklist. This chapter owns\\n      the detailed explanation: random masks, inverted scaling,\\n      <code>train()</code> vs <code>eval()</code>, flattening, and common\\n      mistakes.\\n    </div>\\n\\n    <div class=\\"chips\\">\\n      <span class=\\"chip\\">Conv2d arguments &amp; shapes</span>\\n      <span class=\\"chip\\">nn.Module &amp; inheritance</span>\\n      <span class=\\"chip\\">Sequential vs custom nn.Module</span>\\n      <span class=\\"chip\\">Flatten/view boundary</span>\\n      <span class=\\"chip\\">Dropout: masks, scaling, gradients</span>\\n      <span class=\\"chip\\">train() vs eval()</span>\\n    </div>\\n\\n    <nav>\\n      <a href=\\"#dropout\\">Dropout (updated)</a>\\n      <a href=\\"#train-eval\\">train() vs eval()</a>\\n      <a href=\\"#dropout-faq\\">Dropout FAQ</a>\\n    </nav>\\n  </header>\\n\\n  \x3c!-- (To keep this response focused on your request, only the updated Dropout-related parts are shown below.) --\x3e\\n\\n  <section id=\\"dropout\\">\\n    <h2 id=\\"dropout-what-it-actually-does-and-what-it-does-not-do\\">Dropout: what it actually does (and what it does NOT do)</h2>\\n\\n    <div class=\\"callout\\">\\n      <p style=\\"margin:0;\\">\\n        <b>Correct mental model:</b> Dropout applies a <b>new random mask every forward pass</b> (typically every mini-batch).\\n        It does <b>not</b> permanently \u201cturn off\u201d a neuron, and it does <b>not</b> remove it for the whole training run.\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"what-gets-dropped\\">What gets dropped?</h3>\\n    <p>\\n      In standard dropout, we drop <b>activations</b> (the outputs of a layer), not the parameter tensors directly.\\n      Think: \u201cfor this forward pass, some activation values become zero.\u201d\\n    </p>\\n\\n    <h3 id=\\"training-mode-math-inverted-dropout\\">Training mode math (inverted dropout)</h3>\\n    <p>\\n      Let a layer output be \\\\(h\\\\). Dropout samples a mask \\\\(m\\\\) where:\\n      \\\\[\\n        m_i \\\\sim \\\\mathrm{Bernoulli}(q), \\\\quad q = 1-p\\n      \\\\]\\n      Then it computes:\\n      \\\\[\\n        \\\\tilde{h} = \\\\frac{m \\\\odot h}{q}\\n      \\\\]\\n    </p>\\n    <ul>\\n      <li>If \\\\(m_i = 0\\\\): that activation is <b>zeroed</b> for this pass.</li>\\n      <li>If \\\\(m_i = 1\\\\): it\u2019s kept, and scaled by \\\\(1/q\\\\).</li>\\n      <li>The scaling keeps the <b>expected activation magnitude</b> consistent between training and inference.</li>\\n    </ul>\\n\\n    <h3 id=\\"inference-mode-math\\">Inference mode math</h3>\\n    <p>\\n      In eval mode, dropout is disabled:\\n      \\\\[\\n        \\\\tilde{h} = h\\n      \\\\]\\n      No randomness, no masking.\\n    </p>\\n\\n    <h3 id=\\"what-happens-to-gradients-when-an-activation-is-dropped\\">What happens to gradients when an activation is dropped?</h3>\\n    <p>\\n      When an activation is dropped (\\\\(m_i=0\\\\)), it contributes nothing to the output, so the gradient through that activation is zero for that sample:\\n      \\\\[\\n        \\\\frac{\\\\partial \\\\tilde{h}_i}{\\\\partial h_i} = \\\\frac{m_i}{q}\\n      \\\\]\\n      If \\\\(m_i=0\\\\), then \\\\(\\\\partial \\\\tilde{h}_i / \\\\partial h_i = 0\\\\). Practically:\\n    </p>\\n    <ul>\\n      <li>Weights feeding into that activation receive <b>no update from that sample</b>.</li>\\n      <li>But next iteration, the mask changes, so the same unit may be active and updated then.</li>\\n    </ul>\\n\\n    <figure>\\n      <img alt=\\"Dropout illustration\\" src=\\"/tutorials/images/external/Dropout_en-d57ec7c14c-fallback.svg\\">\\n      <figcaption>\\n        Local book diagram of dropout. Primary reference:\\n        <a href=\\"https://jmlr.org/papers/v15/srivastava14a.html\\" target=\\"_blank\\" rel=\\"noopener\\">Srivastava et al., 2014</a>.\\n      </figcaption>\\n    </figure>\\n\\n    <h3 id=\\"interactive-mini-demo-mask-changes-every-forward-pass\\">Interactive mini-demo (mask changes every \u201cforward pass\u201d)</h3>\\n    <p class=\\"muted\\">\\n      This toy demo uses a vector <span class=\\"mono\\">[1..12]</span> as \u201cactivations\u201d.\\n      Click \u201cRun one forward pass\u201d multiple times in train mode and watch the mask change.\\n    </p>\\n\\n    <div class=\\"demo\\" aria-label=\\"Dropout demo widget\\">\\n      <div class=\\"row\\">\\n        <label>Drop probability p: <b id=\\"pVal\\">0.50</b></label>\\n        <input id=\\"pSlider\\" type=\\"range\\" min=\\"0\\" max=\\"0.9\\" step=\\"0.05\\" value=\\"0.5\\">\\n        <button id=\\"toggleMode\\" type=\\"button\\">Toggle train/eval</button>\\n        <span id=\\"modeOut\\" class=\\"tag warn\\">train (random mask each forward pass)</span>\\n      </div>\\n\\n      <div class=\\"row\\" style=\\"margin-top:10px;\\">\\n        <button id=\\"runDropout\\" type=\\"button\\">Run one forward pass</button>\\n        <span class=\\"muted small\\">Train mode: new random mask each click.</span>\\n      </div>\\n\\n      <div class=\\"kv\\">\\n        <div class=\\"k\\">h (input)</div> <div class=\\"mono\\" id=\\"xOut\\"></div>\\n        <div class=\\"k\\">m (mask)</div>  <div class=\\"mono\\" id=\\"mOut\\"></div>\\n        <div class=\\"k\\">scaling</div>   <div class=\\"mono\\" id=\\"scaleOut\\"></div>\\n        <div class=\\"k\\">h\u0303 (output)</div> <div class=\\"mono\\" id=\\"yOut\\"></div>\\n      </div>\\n    </div>\\n\\n    <h3 id=\\"pytorch-the-exact-behavior-you-should-remember\\">PyTorch: the exact behavior you should remember</h3>\\n    <ul>\\n      <li><code>nn.Dropout(p)</code> applies random masking only when the module is in <code>train()</code> mode.</li>\\n      <li>In <code>eval()</code> mode, it becomes an identity function (no change).</li>\\n      <li>For standard dropout, mask entries are sampled independently for activations during each forward call. Structured variants such as <code>Dropout2d</code> drop whole channels instead.</li>\\n    </ul>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 verify mask randomness in train vs determinism in eval</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\ndrop = nn.Dropout(p=0.5)\\nx = torch.ones(1, 10)\\n\\ndrop.train()\\ny1 = drop(x)\\ny2 = drop(x)  # different mask, usually different output\\n\\ndrop.eval()\\ny3 = drop(x)\\ny4 = drop(x)  # same output, dropout disabled\\n\\nprint(\\"train different:\\", not torch.allclose(y1, y2))\\nprint(\\"eval same:\\", torch.allclose(y3, y4))</code></pre>\\n    </div>\\n\\n    <h3 id=\\"where-to-put-dropout-practical-default\\">Where to put dropout (practical default)</h3>\\n    <p>\\n      Most commonly: between dense layers. For conv feature maps, many projects skip it or use specialized variants.\\n    </p>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 common pattern: Dense \u2192 ReLU \u2192 Dropout \u2192 Dense</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch.nn as nn\\n\\nhead = nn.Sequential(\\n    nn.Linear(512, 256),\\n    nn.ReLU(),\\n    nn.Dropout(p=0.5),\\n    nn.Linear(256, 10)  # logits\\n)</code></pre>\\n    </div>\\n\\n    <p class=\\"muted\\">\\n      For conv nets, you may also see <code>nn.Dropout2d</code> / <code>nn.Dropout3d</code>:\\n      these drop entire channels (feature maps), not individual pixels.\\n    </p>\\n  </section>\\n\\n  <section id=\\"train-eval\\">\\n    <h2 id=\\"train-vs-eval-why-dropout-turns-off-for-predictions\\">train() vs eval(): why dropout \u201cturns off\u201d for predictions</h2>\\n\\n    <p>\\n      PyTorch modules can have different behavior depending on whether you\u2019re training or evaluating.\\n      Dropout is the classic example:\\n    </p>\\n\\n    <ul>\\n      <li><code>model.train()</code> \u2192 dropout ON (random masking), batchnorm uses batch stats</li>\\n      <li><code>model.eval()</code> \u2192 dropout OFF (no masking), batchnorm uses running stats</li>\\n    </ul>\\n\\n    <div class=\\"callout\\">\\n      <p style=\\"margin:0;\\">\\n        <b>Standard pattern:</b> call <code>model.train()</code> before the training loop,\\n        and <code>model.eval()</code> during validation/testing (usually with <code>torch.no_grad()</code>).\\n      </p>\\n    </div>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 training/evaluation skeleton (dropout-safe)</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>model.train()\\nfor xb, yb in train_loader:\\n    optimizer.zero_grad()\\n    logits = model(xb)        # dropout active here\\n    loss = loss_fn(logits, yb)\\n    loss.backward()\\n    optimizer.step()\\n\\nmodel.eval()\\ncorrect = 0\\ntotal = 0\\nwith torch.no_grad():\\n    for xb, yb in val_loader:\\n        logits = model(xb)    # dropout disabled here\\n        preds = logits.argmax(dim=1)\\n        correct += (preds == yb).sum().item()\\n        total += yb.size(0)\\nprint(\\"val acc:\\", correct / total)</code></pre>\\n    </div>\\n  </section>\\n\\n  <section id=\\"dropout-faq\\">\\n    <h2 id=\\"dropout-faq-common-confusions\\">Dropout FAQ (common confusions)</h2>\\n\\n    <h3 id=\\"does-dropout-stop-training-a-random-node-each-iteration\\">\u201cDoes dropout stop training a random node each iteration?\u201d</h3>\\n    <p>\\n      It temporarily <b>zeros a random subset of activations</b> each forward pass.\\n      Those dropped activations have <b>zero gradient for that sample</b>, so their incoming weights don\u2019t update from that sample.\\n      Next iteration, the mask changes, so they can update again.\\n      <span class=\\"tag warn\\">Not permanent</span>\\n    </p>\\n\\n    <h3 id=\\"is-the-same-set-of-nodes-masked-all-the-time\\">\u201cIs the same set of nodes masked all the time?\u201d</h3>\\n    <p>\\n      No\u2014standard dropout resamples a new mask per forward pass.\\n      Some specialized variants (e.g., \u201clocked/variational dropout\u201d in some sequence models) reuse a mask across time steps,\\n      but that\u2019s not the default behavior of <code>nn.Dropout</code>.\\n    </p>\\n\\n    <h3 id=\\"does-dropout-remove-weights\\">\u201cDoes dropout remove weights?\u201d</h3>\\n    <p>\\n      No. The parameters are still there. Dropout modifies the activations during training. At inference, nothing is removed.\\n    </p>\\n\\n    <h3 id=\\"why-is-there-scaling-by-1-1-p\\">\u201cWhy is there scaling by 1/(1-p)?\u201d</h3>\\n    <p>\\n      Without scaling, the average activation magnitude would shrink during training.\\n      Inverted dropout keeps the expected activation scale similar between train and eval.\\n    </p>\\n\\n    <h3 id=\\"should-i-use-dropout-in-conv-layers\\">\u201cShould I use dropout in conv layers?\u201d</h3>\\n    <p>\\n      Often not necessary. If you do, consider channel-wise dropout (<code>Dropout2d</code>) rather than pixel-wise dropout,\\n      and verify by experiment\u2014sometimes it helps, sometimes it\u2019s neutral.\\n    </p>\\n    <p>\\n      In modern CNNs, batch normalization, data augmentation, weight decay, early stopping, and larger datasets often reduce\\n      the need for heavy dropout. Dropout is still valid, but it is a regularization choice to validate, not a mandatory CNN ingredient.\\n    </p>\\n  </section>\\n\\n  <section id=\\"sources\\">\\n    <h2 id=\\"local-visuals-and-source-credits\\">Local visuals and source credits</h2>\\n    <ul class=\\"small\\">\\n      <li>Dropout diagram: local book asset; primary reference: <a href=\\"https://jmlr.org/papers/v15/srivastava14a.html\\" target=\\"_blank\\" rel=\\"noopener\\">Srivastava et al., 2014</a></li>\\n    </ul>\\n    <p class=\\"muted small\\">\\n      This page is self-contained: MathJax renders equations, shared highlighting formats code, and visuals are served from local assets.\\n    </p>\\n  </section>\\n\\n</div>"}'),d={title:"CNN Training in PyTorch: Flattening, Dropout, Train, and Eval",slug:"/part5-deep-learning-and-llms/07-cnn-dropout-train-eval",description:"This chapter develops Dropout from first principles: what gets masked, how often masks change, why scaling exists, how gradients behave, and why train()/eval() matters.",sidebar_label:"7. CNN dropout and train/eval",pagination_label:"7. CNN dropout and train/eval",hide_title:!0,hide_table_of_contents:!0},l=void 0,p={},c=[];function h(n){return(0,o.jsx)(s.A,{content:r})}function u(n={}){const{wrapper:e}={...(0,i.R)(),...n.components};return e?(0,o.jsx)(e,{...n,children:(0,o.jsx)(h,{...n})}):h()}}}]);